    choices: [
      { key: 'A', text: '電気室には、変圧器等の重量機器の搬入・搬出を考慮した搬入経路・開口部を計画する必要がある。', explanation: '適当。重量機器の更新・搬入を見据えた計画が必要である。' },
      { key: 'B', text: '電気室の床は、設置する機器の重量に耐える十分な床荷重（積載荷重）を確保する必要がある。', explanation: '適当。機器重量に応じた構造検討が必要である。' },
      { key: 'C', text: '電気室の天井高さは、機器の高さや点検・引出しに必要な上部スペースを考慮して計画する。', explanation: '適当。保守性を確保するための計画事項である。' },
      { key: 'D', text: '電気室は建築物のどこに配置してもよく、浸水・延焼・騒音・振動等、周辺への影響や設置環境は計画上考慮する必要がない。', explanation: '不適当。電気室の配置計画では、浸水リスクの低い階への配置、火災延焼防止のための防火区画、周辺居室への騒音・振動の配慮等、設置環境に関する多面的な検討が不可欠である。「考慮する必要がない」は誤りである。' },
    ],
    correctKey: 'D',
    explanation: '電気室の配置計画では搬入経路・床荷重・天井高さに加え、浸水・延焼・騒音・振動等、周辺環境への配慮が不可欠である。\n【図解】電気室の建築計画\n　○重量機器の搬入経路・開口部の確保\n　○床荷重（積載荷重）、天井高さ（点検・引出しスペース）\n　★浸水リスク・防火区画・騒音振動対策も重要な検討事項\n　×「配置・環境は考慮不要」は誤り⚠\n　→ 建築計画段階から設備更新性・防災性を織り込む',
    difficulty: 'basic',
