    question: 'コージェネレーションシステムの排熱利用形態に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'コージェネレーションシステムは、発電時に生じる排熱を、給湯・暖房・蒸気供給等に利用することで、総合的なエネルギー利用効率を高めるシステムである。', explanation: '適当。コージェネレーションシステムの基本的な考え方である。' },
      { key: 'B', text: '排熱は、吸収冷凍機の熱源として利用し、冷房（冷熱）を供給することも可能である。', explanation: '適当。排熱利用の代表的な応用例である。' },
      { key: 'C', text: '排熱利用の有無にかかわらず、コージェネレーションシステムの発電効率（電気出力のみの効率）自体は変化しない。', explanation: '適当。排熱利用は総合エネルギー利用効率（電気＋熱）を高める効果であり、発電効率（電気出力のみの効率）自体はエンジン・発電機の性能で決まり、排熱利用の有無で変化するものではない。' },
      { key: 'D', text: 'コージェネレーションシステムは排熱を一切利用せず、発電のみを行うシステムであり、通常の発電設備と総合エネルギー効率の面で何ら変わりはない。', explanation: '不適当。コージェネレーション（熱電併給）システムは、その名のとおり発電に加えて排熱を給湯・暖房・冷房等に有効利用することで、通常の発電設備単体に比べて総合的なエネルギー利用効率を高めることを目的としたシステムである。「排熱を一切利用せず通常の発電設備と変わらない」は、コージェネレーションの定義そのものに反する誤りである。' },
    ],
    correctKey: 'D',
    explanation: 'コージェネレーションシステムは排熱を給湯・暖房・冷房等に利用し総合エネルギー効率を高めるシステムであり、「排熱を一切利用しない」は定義に反する誤り。\n【図解】コージェネレーションの排熱利用\n　○排熱を給湯・暖房・蒸気供給に利用\n　○吸収冷凍機の熱源として冷房にも利用可能\n　○排熱利用の有無で発電効率自体は変化しない（総合効率が変わる）\n　×「排熱を一切利用しない」は定義に反する誤り⚠\n　→ 排熱の有効利用こそがコージェネレーションの本質',
    difficulty: 'standard',
