    question: '構内電気設備におけるハーモニックフィルタ（受動フィルタ）の設計に関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '受動フィルタ（LCフィルタ）は、特定の高調波次数に共振するようインダクタンスとキャパシタンスを調整し、当該次数の高調波電流を吸収する構成が一般的である。', explanation: '適当。受動フィルタの基本構成である。' },
      { key: 'B', text: '受動フィルタは、対象とする高調波次数があらかじめ想定と異なる（負荷構成の変化等）場合、十分な抑制効果が得られないことがある。', explanation: '適当。受動フィルタの制約事項である。' },
      { key: 'C', text: '受動フィルタは、系統側のインピーダンスとの関係によっては、想定していない次数の高調波を増幅（共振拡大）してしまうおそれがあるため、設計時の検討が重要である。', explanation: '適当。受動フィルタ設計上のリスクである。' },
      { key: 'D', text: '受動フィルタは、いかなる系統条件・負荷条件においても、追加の検討なく設置するだけで全ての高調波次数を完全に除去できる万能な装置である。', explanation: '不適当。受動フィルタ（LCフィルタ）は特定の高調波次数に対して設計・調整されるものであり、全ての次数の高調波を無条件に完全除去できる万能な装置ではない。系統インピーダンスとの相互作用により想定外の共振・増幅を招くおそれもあるため、設置にあたっては系統・負荷条件を踏まえた十分な検討が不可欠であり、「追加の検討なく全次数を完全除去できる」は誤りである。' },
    ],
    correctKey: 'D',
    explanation: '受動フィルタは特定次数の高調波を対象に設計されるものであり、系統インピーダンスとの相互作用で想定外の共振を招くこともあるため、設置には十分な事前検討が必要である。\n【図解】ハーモニックフィルタ（受動フィルタ）\n　○LCの共振により特定次数の高調波電流を吸収\n　○負荷構成の変化で想定外の次数には効果が薄れる\n　★系統インピーダンスとの共振拡大リスクに注意\n　×「検討なしで全次数を完全除去できる万能装置」は誤り⚠\n　→ 系統・負荷条件を踏まえた事前の設計検討が不可欠',
