    explanation: '環境関係法令の適用可否は設備の出力規模等の要件により定まるものであり、「非常用だから一律に適用除外」とはならない。\n【図解】非常用発電設備の排出ガス規制\n　○出力規模等に応じ大気汚染防止法上の規制対象となり得る\n　○NOx・ばいじん等の排出基準の遵守が求められる場合がある\n　○平常時の負荷試験運転にも環境配慮が必要\n　×「非常用だから一律に適用除外」は誤り⚠\n　→ 規模要件を満たせば届出・排出基準遵守が必要',
